const now = new Date();
const domingo = new Date(now);
domingo.setHours(0, 0, 0, 0);
const lunes = new Date(domingo);
lunes.setDate(domingo.getDate() - 6);
const fmt = d => d.toISOString().split('T')[0];
return [{ json: { fechaDesde: fmt(lunes), fechaHasta: fmt(domingo) } }];

const results = $input.item.json.results || [];

const entradas = results.map(e => {
  const p = e.properties;
  const concepto  = p.Concepto?.title?.[0]?.plain_text || 'Sin nombre';
  const monto     = p.Monto?.number || 0;
  const realizado = p.Realizado?.checkbox || false;
  return { concepto, monto, realizado };
});

const ingresos = entradas.filter(e => e.monto > 0);
const egresos  = entradas.filter(e => e.monto < 0).map(e => ({ ...e, monto: Math.abs(e.monto) }));

const totalCobrado = ingresos.filter(e => e.realizado).reduce((s, e) => s + e.monto, 0);
const totalGastado = egresos.filter(e => e.realizado).reduce((s, e) => s + e.monto, 0);
const neto = totalCobrado - totalGastado;

const fmt = n => '$' + n.toLocaleString('es-AR', { minimumFractionDigits: 2 });
const fila = ({ concepto, monto, realizado }) =>
  `  ${realizado ? '✅' : '⏳'} ${concepto}: *${fmt(monto)}*`;

const ingresosLines = ingresos.length ? ingresos.map(fila).join('
') : '  Nada. Ni un peso, gloriosos.';
const egresosLines  = egresos.length  ? egresos.map(fila).join('
')  : '  Milagrosamente, nada.';

const fechaDesde = $('Calcular fechas').item.json.fechaDesde;
const fechaHasta = $('Calcular fechas').item.json.fechaHasta;
const fmtDate = s => { const [y,m,d] = s.split('-'); return `${d}/${m}`; };
const rango = `${fmtDate(fechaDesde)} al ${fmtDate(fechaHasta)}/${fechaHasta.split('-')[0]}`;

const nivelTono = totalCobrado < 1000
  ? 'PELIGRO: menos de $1.000 cobrado. Tono de alarma total, drama, como si la empresa estuviera en llamas. Urgente y sarcástico.'
  : totalCobrado < 2000
  ? 'NEUTRO: entre $1.000 y $2.000. Tono de "no están tan arruinados, sigan así". Ni eufórico ni catastrófico.'
  : 'ÉXITO: más de $2.000. Tono eufórico y motivador. Llamalos "toros". Mencioná el Porsche, el éxito, que sigan metiéndole.';

const prompt = `Sos el bot financiero sarcástico de la agencia, una agencia de automatización con IA. Tu trabajo es mandar el reporte semanal al equipo con un tono irreverente, gracioso y directo.

DATOS DE LA SEMANA (${rango}):

INGRESOS:
${ingresosLines}

EGRESOS:
${egresosLines}

COBRADO: ${fmt(totalCobrado)}
GASTADO: ${fmt(totalGastado)}
NETO: ${fmt(neto)}

TONO A USAR: ${nivelTono}

Generá el reporte completo en este formato exacto para Telegram (Markdown):

📊 *REPORTE SEMANAL — ${rango}*
_(frase sarcástica tuya como bot)_

💰 *ENTRÓ*
${ingresosLines}

🔥 *SALIÓ*
${egresosLines}

━━━━━━━━━━━━━━━
📥 Cobrado: *${fmt(totalCobrado)}*
📤 Gastado: *${fmt(totalGastado)}*
🏦 Neto: *${fmt(neto)}*

[mensaje final gracioso acorde al tono indicado, 1-2 líneas con emojis]

Reglas:
- Usá los números y listas exactamente como están arriba, no los cambies
- Solo devolvé el mensaje, sin explicaciones ni texto extra
- El mensaje final tiene que ser fresco, distinto cada semana, nunca genérico`;

return [{ json: { prompt } }];
